// Primary-button reference only; other components follow DESIGN.md.
struct WoodenPrimaryButtonStyle: ButtonStyle {
    @Environment(\.isEnabled) private var isEnabled
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    func makeBody(configuration: Configuration) -> some View {
        let pressed = configuration.isPressed && isEnabled
        let shape = RoundedRectangle(cornerRadius: WoodlandTokens.Radius.control, style: .continuous)
        let face = isEnabled ? WoodlandTokens.Palette.actionPrimary : WoodlandTokens.Palette.disabledFill
        let ink = isEnabled ? WoodlandTokens.Palette.onPrimary : WoodlandTokens.Palette.disabledInk
        let side = isEnabled ? WoodlandTokens.Palette.actionPrimarySide : WoodlandTokens.Palette.disabledStroke
        let depth = WoodlandTokens.Motion.restDepth
        let travel = pressed ? WoodlandTokens.Motion.pressTravel : 0
        configuration.label
            .modifier(WoodlandTextStyle(role: WoodlandTokens.Typography.label))
            .multilineTextAlignment(.center)
            .padding(.horizontal, WoodlandTokens.Spacing.lg)
            .padding(.vertical, WoodlandTokens.Spacing.md)
            .frame(maxWidth: .infinity, minHeight: WoodlandTokens.Size.touchMinimum)
            .foregroundStyle(ink)
            .background(shape.fill(face))
            .overlay(shape.strokeBorder(isEnabled ? Color.white.opacity(0.3) : WoodlandTokens.Palette.disabledStroke, lineWidth: WoodlandTokens.Stroke.hairline))
            .offset(y: reduceMotion ? 0 : CGFloat(travel))
            .background {
                shape.fill(side).offset(y: CGFloat(depth))
                    .shadow(color: WoodlandTokens.Palette.textPrimary.opacity(pressed ? 0.12 : 0.18), radius: pressed ? 2.0 : 8.0, x: 0, y: pressed ? 2 : 8)
            }
            .contentShape(shape)
            .animation(reduceMotion ? nil : .easeOut(duration: WoodlandTokens.Motion.pressDuration), value: pressed)
    }
}

// Scales the specified base size; do not replace with a fixed-size Font.
struct WoodlandTextStyle: ViewModifier {
    let role: WoodlandTokens.TypeRole
    @ScaledMetric private var pointSize: CGFloat
    @ScaledMetric private var extraLeading: CGFloat
    init(role: WoodlandTokens.TypeRole) {
        self.role = role
        _pointSize = ScaledMetric(wrappedValue: role.size, relativeTo: role.textStyle)
        _extraLeading = ScaledMetric(wrappedValue: max(0, role.lineHeight - role.size), relativeTo: role.textStyle)
    }
    func body(content: Content) -> some View {
        content.font(.system(size: pointSize, weight: role.weight, design: .rounded))
            .lineSpacing(extraLeading)
    }
}
